    private final CreativeFileEntityProjector projector;
	private final CreativeFileValidator validator;
	private CreativeFile creativeFile 	= null;
	private CurrentIdentity identity			= null;
	private static final Logger LOGGER 			=  LoggerFactory.getLogger(CreativeFileService.class);
